function roster(s) {
  return `<div class="panel"><div class="panel-label">BUILD YOUR CORE <span>${s.trained.length}/2 TRAINING SLOTS USED</span></div><p class="intro">Train for +2 OVR ($3M), up to each player's ceiling. Trade one veteran per season before week 7 for $5M and ${s.phase === "offseason" && !s.draftComplete ? "an extra selection in this draft" : "an extra selection in next offseason’s draft"}; heat rises by ${Game.weightedHeat(s, 5)}.</p><div class="roster-list">${s.roster.map((p, i) => `<div class="player"><span class="position">${p.pos}</span><div class="player-name"><b>${p.name}</b><small>AGE ${p.age} · CEILING ${p.potential} · ${money(p.salary)}/YR · ${p.years}Y</small></div><strong class="rating">${round(p.rating)}</strong><div class="player-actions">${button(s.trained.includes(i) ? "Trained ✓" : "Train · $3M", "train:" + i, !Game.canManage(s) || Game.spendable(s) < 3 || s.trained.length >= 2 || s.trained.includes(i) || p.rating >= p.potential)}${button("Trade", "trade:" + i, !["offseason", "regular"].includes(s.phase) || s.week >= 6 || !!s.tradedThisSeason || p.rating < 60, "subtle")}</div></div>`).join("")}</div></div>`;
}
